/**
 * Concatenates every migration, in order, plus the seed, into one file that
 * can be pasted into the Supabase SQL Editor in a single go.
 *
 * This exists so that setting up a database does not require installing the
 * Supabase CLI and authenticating it — the dashboard's SQL Editor is enough.
 * `supabase db push` remains the right tool for a real deployment, where
 * migrations need to be applied incrementally to a database that already has
 * data in it. This is for standing up an empty one.
 *
 * The output is generated fresh each time and written to a gitignored
 * directory on purpose. A committed copy would silently fall out of step with
 * supabase/migrations/ the first time anyone added a migration and forgot to
 * regenerate it — and a stale bootstrap that appears to work is worse than no
 * bootstrap at all.
 *
 *   npm run db:bundle
 */

import { readFileSync, writeFileSync, mkdirSync, readdirSync } from "node:fs";
import { join } from "node:path";

const MIGRATIONS = "supabase/migrations";
const OUT_DIR = "exports";
const OUT = join(OUT_DIR, "bootstrap.sql");

const files = readdirSync(MIGRATIONS)
  .filter((f) => f.endsWith(".sql"))
  .sort(); // 0001_, 0002_, … — zero-padded so lexical order is real order

if (files.length === 0) {
  console.error(`No migrations found in ${MIGRATIONS}.`);
  process.exit(1);
}

const parts = [
  `-- Tic Tac Tooth — complete database bootstrap`,
  `-- Generated by scripts/build-sql-bundle.mjs on ${new Date().toISOString()}`,
  `--`,
  `-- ${files.length} migrations plus the configuration seed, in order.`,
  `-- Run this once against an EMPTY database. It is not incremental and`,
  `-- re-running it on a database that already has data is not safe.`,
  `--`,
  `-- Contains no patient data and must never be given any.`,
  ``,
];

for (const f of files) {
  parts.push(
    ``,
    `-- ${"=".repeat(74)}`,
    `-- ${f}`,
    `-- ${"=".repeat(74)}`,
    ``,
    readFileSync(join(MIGRATIONS, f), "utf8").trimEnd(),
    ``
  );
}

parts.push(
  ``,
  `-- ${"=".repeat(74)}`,
  `-- seed.sql — configuration only`,
  `-- ${"=".repeat(74)}`,
  ``,
  readFileSync("supabase/seed.sql", "utf8").trimEnd(),
  ``
);

mkdirSync(OUT_DIR, { recursive: true });
writeFileSync(OUT, parts.join("\n"), "utf8");

console.log(`\n  Wrote ${OUT}`);
console.log(`  ${files.length} migrations + seed\n`);
for (const f of files) console.log(`    ${f}`);
console.log(`    seed.sql\n`);
console.log(`  Paste the whole file into the Supabase SQL Editor and Run.\n`);
